#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>

using namespace std;

const int INF = 1e9 + 7;
const int MAXLOG = 18;

struct Edge {
    int u, v, w;
    bool operator<(const Edge& other) const {
        return w > other.w; // Maior capacidade primeiro para MST máxima
    }
};

struct TreeEdge {
    int to, weight;
};

struct DSU {
    vector<int> parent;
    DSU(int n) {
        parent.resize(n + 1);
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int i) {
        if (parent[i] == i)
            return i;
        return parent[i] = find(parent[i]);
    }
    bool unite(int i, int j) {
        int root_i = find(i);
        int root_j = find(j);
        if (root_i != root_j) {
            parent[root_i] = root_j;
            return true;
        }
        return false;
    }
};

int N, B;
vector<vector<TreeEdge>> adj;
int up[100005][MAXLOG];
int min_weight[100005][MAXLOG];
int depth[100005];

void dfs(int u, int p, int d, int w) {
    depth[u] = d;
    up[u][0] = p;
    min_weight[u][0] = w;

    for (int i = 1; i < MAXLOG; ++i) {
        up[u][i] = up[up[u][i - 1]][i - 1];
        min_weight[u][i] = min(min_weight[u][i - 1], min_weight[up[u][i - 1]][i - 1]);
    }

    for (const auto& edge : adj[u]) {
        if (edge.to != p) {
            dfs(edge.to, u, d + 1, edge.weight);
        }
    }
}

int query(int u, int v) {
    int ans = INF;

    if (depth[u] < depth[v]) {
        swap(u, v);
    }

    for (int i = MAXLOG - 1; i >= 0; --i) {
        if (depth[u] - (1 << i) >= depth[v]) {
            ans = min(ans, min_weight[u][i]);
            u = up[u][i];
        }
    }

    if (u == v) return ans;

    for (int i = MAXLOG - 1; i >= 0; --i) {
        if (up[u][i] != up[v][i]) {
            ans = min(ans, min_weight[u][i]);
            ans = min(ans, min_weight[v][i]);
            u = up[u][i];
            v = up[v][i];
        }
    }

    ans = min(ans, min_weight[u][0]);
    ans = min(ans, min_weight[v][0]);

    return ans;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    if (!(cin >> N >> B)) return 0;

    vector<Edge> edges(B);
    for (int i = 0; i < B; ++i) {
        cin >> edges[i].u >> edges[i].v >> edges[i].w;
    }

    sort(edges.begin(), edges.end());

    DSU dsu(N);
    adj.resize(N + 1);

    int edges_count = 0;
    for (const auto& edge : edges) {
        if (dsu.unite(edge.u, edge.v)) {
            adj[edge.u].push_back({edge.v, edge.w});
            adj[edge.v].push_back({edge.u, edge.w});
            edges_count++;
            if (edges_count == N - 1) break;
        }
    }

    dfs(1, 1, 0, INF);

    int C;
    if (cin >> C) {
        while (C--) {
            int x, y;
            cin >> x >> y;
            cout << query(x, y) << "\n";
        }
    }

    return 0;
}
